/**
 * `pending` until the instance is created: before the order is accepted no instance exists and addresses are null. Then `running`. `failed` means the instance was not created; `failure_reason` states why. The other values are the state of the instance in the cloud. A value naming an operation in progress (`starting`, `stopping`, `rebooting`, `rebuilding`, `rescuing`, `unrescuing`, `resizing`, `resetting_password`, `attaching_volume`, `detaching_volume`, `attaching_network_interface`, `detaching_network_interface`, `associating_elastic_ip`, `disassociating_elastic_ip`, `capturing_image`, `suspending`, `resuming`, `deleting`) is shown while that operation runs; the instance refuses another operation until it ends.
 */
export type InstanceStatus = (typeof InstanceStatus)[keyof typeof InstanceStatus];

export const InstanceStatus = {
  pending: "pending",
  running: "running",
  stopped: "stopped",
  paused: "paused",
  suspended: "suspended",
  rescued: "rescued",
  deleted: "deleted",
  failed: "failed",
  error: "error",
  starting: "starting",
  stopping: "stopping",
  rebooting: "rebooting",
  rebuilding: "rebuilding",
  rescuing: "rescuing",
  unrescuing: "unrescuing",
  resizing: "resizing",
  resetting_password: "resetting_password",
  attaching_volume: "attaching_volume",
  detaching_volume: "detaching_volume",
  attaching_network_interface: "attaching_network_interface",
  detaching_network_interface: "detaching_network_interface",
  associating_elastic_ip: "associating_elastic_ip",
  disassociating_elastic_ip: "disassociating_elastic_ip",
  capturing_image: "capturing_image",
  suspending: "suspending",
  resuming: "resuming",
  deleting: "deleting",
} as const;

/**
 * Why it is held. `operator_suspended` is a suspension by the platform. `billing_suspended` is the instance's
 * own subscription suspended for non-payment, and `billing_reclaimed` that subscription ending,
 * after which the instance is released. `boot_volume_suspended` and `boot_volume_reclaimed` are the same
 * for the subscription of the volume the instance boots from: that volume is billed apart, and the
 * instance cannot run without it, so renewing the volume's subscription lifts the hold, and a reclaimed
 * boot volume is released together with its instance.
 */
export type InstanceRestrictionReason =
  (typeof InstanceRestrictionReason)[keyof typeof InstanceRestrictionReason];

export const InstanceRestrictionReason = {
  operator_suspended: "operator_suspended",
  billing_suspended: "billing_suspended",
  billing_reclaimed: "billing_reclaimed",
  boot_volume_suspended: "boot_volume_suspended",
  boot_volume_reclaimed: "boot_volume_reclaimed",
} as const;

/**
 * One hold on the instance. While any holds it, the instance is stopped and refuses being started,
 * rebooted, rebuilt, resized, rescued, having its password reset and running commands, with 409
 * `INSTANCE_SUSPENDED`. Holds are independent: lifting one never lifts another, and once none remains
 * the instance is started again only if a hold stopped it, never one its user stopped.
 */
export interface InstanceRestriction {
  /**
   * Why it is held. `operator_suspended` is a suspension by the platform. `billing_suspended` is the instance's
   * own subscription suspended for non-payment, and `billing_reclaimed` that subscription ending,
   * after which the instance is released. `boot_volume_suspended` and `boot_volume_reclaimed` are the same
   * for the subscription of the volume the instance boots from: that volume is billed apart, and the
   * instance cannot run without it, so renewing the volume's subscription lifts the hold, and a reclaimed
   * boot volume is released together with its instance.
   */
  reason: InstanceRestrictionReason;
  /**
   * The Billing subscription whose state holds the instance; null for `operator_suspended`.
   * @nullable
   */
  subscription_id: string | null;
  /** The volume the instance boots from, for `boot_volume_suspended` and `boot_volume_reclaimed`; null otherwise. */
  volume_id: VolumeID | null;
  /**
   * When the hold began; null when that instant was not recorded.
   * @nullable
   */
  started_at: string | null;
}

/**
 * Why creation failed; null unless `status` is `failed`. `checkout_expired` means checkout was not completed before its Checkout Session expired. `provisioning_failed` means creation failed after the order was accepted, and the charge for this instance is refunded.
 * @nullable
 */
export type InstanceFailureReason =
  | (typeof InstanceFailureReason)[keyof typeof InstanceFailureReason]
  | null;

export const InstanceFailureReason = {
  order_declined: "order_declined",
  order_canceled: "order_canceled",
  order_expired: "order_expired",
  checkout_expired: "checkout_expired",
  provisioning_failed: "provisioning_failed",
} as const;

/**
 * @nullable
 */
export type InstanceAccessState =
  | (typeof InstanceAccessState)[keyof typeof InstanceAccessState]
  | null;

export const InstanceAccessState = {
  pending: "pending",
  enabled: "enabled",
  suspended: "suspended",
  reclaimed: "reclaimed",
} as const;

